import json
import os
import joblib
import pandas as pd
from sklearn.metrics import accuracy_score, classification_report, confusion_matrix
from sklearn.model_selection import train_test_split

try:
    from backend.ml.preprocess import preprocess_text
except ImportError:
    from preprocess import preprocess_text

LABELS = ["Emergency", "Urgent", "Routine"]

# Unseen natural-language patient narratives (not generated by dataset_generator.py templates)
UNSEEN_NATURAL_CASES = [
    # Emergency (8)
    ("I am experiencing severe crushing chest pain, coming down my left arm, and I suddenly have a lot of difficulty breathing.", "Emergency"),
    ("My husband suddenly cannot move his right arm, his speech is slurred, and one side of his face is drooping.", "Emergency"),
    ("My lips and tongue are swelling rapidly after eating peanuts and I am wheezing hard.", "Emergency"),
    ("Deep laceration on my forearm and bright red blood will not stop gushing out even with pressure.", "Emergency"),
    ("Friend fainted and is having convulsions on the floor, barely waking up.", "Emergency"),
    ("Woke up gasping for air with intense squeezing pain in the center of my chest and cold sweat.", "Emergency"),
    ("Sudden loss of vision in one eye with severe dizziness and numbness down my left leg.", "Emergency"),
    ("Severe allergic reaction with hives, tight throat, and trouble inhaling air.", "Emergency"),
    # Urgent (8)
    ("Head hurts rly bad cant sleep coughing alot feeling terrible since yesterday.", "Urgent"),
    ("I have had a temperature of 103F with shaking chills and painful urination since last night.", "Urgent"),
    ("Fell off the stairs and twisted my ankle, it is huge and swollen and I cannot stand on it.", "Urgent"),
    ("Thrown up six times since morning and cannot keep even water down, stomach cramps are bad.", "Urgent"),
    ("Horrible throbbing migraine with sensitivity to light that kept me awake all night.", "Urgent"),
    ("My lower back locked up with sharp radiating pain and I can barely walk today.", "Urgent"),
    ("Deeply infected cut on my hand that is hot, red, and throbbing with pus since two days ago.", "Urgent"),
    ("Severe ear pain and high fever in my child since yesterday evening.", "Urgent"),
    # Routine (8)
    ("I need a routine blood pressure follow up appointment, and need my medication prescription refilled with a standard prescription.", "Routine"),
    ("Looking to renew my daily cholesterol tablets for the next three months.", "Routine"),
    ("Mild stuffy nose and occasional dry cough for three days, feeling okay overall.", "Routine"),
    ("Just want to review my recent annual blood test results with a doctor next week.", "Routine"),
    ("Small itchy dry patch on my elbow for a few days, no fever or pain.", "Routine"),
    ("Slightly tired after work this week and mild neck stiffness from sitting at my desk.", "Routine"),
    ("Need a standard repeat prescription for my seasonal allergy nasal spray.", "Routine"),
    ("Minor sore throat since yesterday morning, drinking tea helps and no temperature.", "Routine"),
]


def evaluate():
    base_dir = os.path.dirname(__file__)
    csv_path = os.path.join(base_dir, "symptom_data.csv")
    model_path = os.path.join(base_dir, "triage_model.pkl")

    df = pd.read_csv(csv_path).drop_duplicates(subset=["symptom_text"]).reset_index(drop=True)
    df["processed_text"] = df["symptom_text"].apply(preprocess_text)
    _, X_test, _, y_test = train_test_split(
        df["processed_text"], df["triage_level"], test_size=0.2, random_state=42, stratify=df["triage_level"]
    )

    model = joblib.load(model_path)
    y_pred = model.predict(X_test)
    synth_acc = float(accuracy_score(y_test, y_pred))
    synth_report = classification_report(y_test, y_pred, labels=LABELS, output_dict=True)
    synth_cm = confusion_matrix(y_test, y_pred, labels=LABELS)

    unseen_texts = [preprocess_text(t) for t, _ in UNSEEN_NATURAL_CASES]
    unseen_true = [y for _, y in UNSEEN_NATURAL_CASES]
    unseen_pred = list(model.predict(unseen_texts))
    unseen_acc = float(accuracy_score(unseen_true, unseen_pred))
    unseen_report = classification_report(unseen_true, unseen_pred, labels=LABELS, output_dict=True)
    unseen_cm = confusion_matrix(unseen_true, unseen_pred, labels=LABELS)

    misclassified = [
        {"text": t, "true": y_t, "pred": y_p}
        for (t, y_t), y_p in zip(UNSEEN_NATURAL_CASES, unseen_pred)
        if y_t != y_p
    ]

    out = {
        "model_bytes": int(os.path.getsize(model_path)),
        "synthetic_holdout": {
            "test_rows": int(len(y_test)),
            "accuracy": synth_acc,
            "confusion_matrix": synth_cm.tolist(),
            "classification_report": synth_report,
        },
        "unseen_natural_holdout": {
            "test_rows": len(UNSEEN_NATURAL_CASES),
            "accuracy": unseen_acc,
            "confusion_matrix": unseen_cm.tolist(),
            "classification_report": unseen_report,
            "misclassified": misclassified,
        },
    }

    out_path = os.path.join(base_dir, "evaluation_results.json")
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=2)

    print(f"Synthetic 20% Holdout ({len(y_test)} rows) Accuracy: {synth_acc:.4f}")
    print(f"Unseen Natural Holdout ({len(UNSEEN_NATURAL_CASES)} rows) Accuracy: {unseen_acc:.4f}")
    print("Unseen Confusion Matrix [Emergency, Urgent, Routine]:\n", unseen_cm)
    if misclassified:
        print("Misclassified unseen cases:", misclassified)
    print(f"Saved evaluation results to {out_path}")


if __name__ == "__main__":
    evaluate()
